import { Head, Link, useForm } from '@inertiajs/react';
import { ArrowLeft, Save, Upload } from 'lucide-react';
import { useEffect, useState } from 'react';
import VendorLayout from '../../../Layouts/VendorLayout';

export default function Create({ categories = [] }) {
    const form = useForm({ category_id: '', name: '', description: '', price: '', stock: '', status: 'active', image: null });
    return <ProductFormPage title="Tambah Produk Baru" description="Tambahkan produk ke katalog toko Anda." form={form} categories={categories} submitLabel="Simpan Produk" submitUrl="/vendor/products" method="post" />;
}

export function ProductFormPage({ title, description, form, categories, submitLabel, submitUrl, method, existingImage = null }) {
    const [preview, setPreview] = useState(existingImage);
    useEffect(() => () => preview?.startsWith('blob:') && URL.revokeObjectURL(preview), [preview]);
    const submit = (event) => { event.preventDefault(); form[method](submitUrl, { forceFormData: true }); };
    const imageChange = (event) => { const file = event.target.files[0] ?? null; if (preview?.startsWith('blob:')) URL.revokeObjectURL(preview); setPreview(file ? URL.createObjectURL(file) : existingImage); form.setData('image', file); };
    const field = (name) => ({ id: name, name, value: form.data[name], onChange: (event) => form.setData(name, event.target.value), 'aria-invalid': Boolean(form.errors[name]) });
    return <VendorLayout><Head title={title} /><main className="min-h-screen bg-background px-5 py-8 text-foreground sm:px-8 lg:px-10"><div className="mx-auto max-w-4xl"><Link href="/vendor/products" className="inline-flex items-center gap-2 text-sm font-semibold text-secondary hover:text-primary"><ArrowLeft size={17} />Kembali ke Produk</Link><header className="mt-6 border-b border-surface-container-high pb-7"><h1 className="font-heading text-3xl font-bold tracking-tight sm:text-4xl">{title}</h1><p className="mt-2 text-base text-secondary">{description}</p></header><form onSubmit={submit} className="mt-8 space-y-6 rounded-xl border border-surface-container-high bg-white p-5 shadow-sm sm:p-8"><div className="grid gap-6 sm:grid-cols-2"><Field label="Nama Produk" name="name" error={form.errors.name} input={field('name')} placeholder="Contoh: Wireless Headphone" /><Field label="Kategori" name="category_id" error={form.errors.category_id} input={field('category_id')} type="select"><option value="">Pilih kategori</option>{categories.map((category) => <option value={category.id} key={category.id}>{category.name}</option>)}</Field><Field label="Harga" name="price" error={form.errors.price} input={field('price')} type="number" min="0" step="0.01" placeholder="0" /><Field label="Stok" name="stock" error={form.errors.stock} input={field('stock')} type="number" min="0" step="1" placeholder="0" /><Field label="Status" name="status" error={form.errors.status} input={field('status')} type="select"><option value="active">Aktif</option><option value="inactive">Nonaktif</option></Field></div><Field label="Deskripsi" name="description" error={form.errors.description} input={field('description')} type="textarea" placeholder="Jelaskan produk Anda..." /><div><p className="mb-2 text-sm font-semibold">Gambar Produk</p><div className="flex flex-col gap-4 sm:flex-row">{preview && <img src={preview} alt="Preview produk" className="h-40 w-full rounded-lg border border-surface-container-high object-cover sm:w-40" />}<label htmlFor="image" className="flex min-w-0 flex-1 cursor-pointer items-center gap-4 rounded-lg border border-dashed border-surface-container-high bg-surface-container-low p-5 outline-none transition-colors hover:border-primary focus-within:border-primary focus-within:ring-2 focus-within:ring-primary/20"><input id="image" name="image" type="file" accept="image/jpeg,image/png,image/webp" onChange={imageChange} className="sr-only" aria-invalid={Boolean(form.errors.image)} aria-describedby={form.errors.image ? 'image-hint image-error' : 'image-hint'} /><span className="flex size-11 shrink-0 items-center justify-center rounded-lg bg-white text-primary shadow-sm"><Upload size={20} aria-hidden="true" /></span><span className="min-w-0"><span className="block text-sm font-semibold text-primary">Pilih Gambar</span>{form.data.image && <span className="mt-1 block truncate text-sm text-foreground" title={form.data.image.name}>{form.data.image.name}</span>}<span id="image-hint" className="mt-1 block text-xs text-secondary">JPEG, PNG, atau WebP, maksimum 5 MB.</span></span></label></div>{form.errors.image && <p id="image-error" className="mt-1.5 text-sm text-error" role="alert">{form.errors.image}</p>}</div><div className="flex flex-col-reverse gap-3 border-t border-surface-container-high pt-6 sm:flex-row sm:justify-end"><Link href="/vendor/products" className="inline-flex items-center justify-center rounded-lg border border-surface-container-high px-4 py-2.5 text-sm font-semibold">Batal</Link><button disabled={form.processing} className="inline-flex items-center justify-center gap-2 rounded-lg bg-primary-container px-4 py-2.5 text-sm font-bold text-white disabled:opacity-50"><Save size={17} />{form.processing ? 'Menyimpan...' : submitLabel}</button></div></form></div></main></VendorLayout>;
}

function Field({ label, name, error, input, type = 'text', children, ...props }) { return <div className={type === 'textarea' ? 'sm:col-span-2' : ''}><label htmlFor={name} className="mb-2 block text-sm font-semibold">{label}</label>{type === 'select' ? <select {...input} {...props} className="w-full rounded-lg border border-surface-container-high bg-white px-3 py-2.5 outline-none focus:border-primary">{children}</select> : type === 'textarea' ? <textarea {...input} {...props} rows="5" className="w-full rounded-lg border border-surface-container-high bg-white px-3 py-2.5 outline-none focus:border-primary" /> : <input {...input} {...props} type={type} className="w-full rounded-lg border border-surface-container-high bg-white px-3 py-2.5 outline-none focus:border-primary" />}{error && <p className="mt-1.5 text-sm text-error" role="alert">{error}</p>}</div>; }